select OBJECT_NAME,OBJECT_TYPE,STATUS from USER_OBJECTS where OBJECT_NAME in('RRL_STOCK_TARE_POLICY','RRL_STOCK_TARE_CMD','RRL_TARE_STORE_DEBT','RRL_TARE_POLICY_GUARD','RRL_TARE_DELIVERY_POLICY_GUARD') order by OBJECT_NAME,OBJECT_TYPE;
select MIGRATION_ID,STATUS from RRL_SCHEMA_MIGRATIONS where MIGRATION_ID='2026-10-10-099-tare-return-deadlines';
select count(*) INVALID_DEBT from RRL_TARE_STORE_DEBT where OUTSTANDING_QTY<0 or OUTSTANDING_QTY>ACCEPTED_QTY;
